(6089078, 896499, 27686, '<td valign="top">The pic looks out of focus</td>', 'The pic looks out of focus', '2010-07-12 03:24:16.000000', NULL, 1),
(6089079, 896922, 96751, '<td valign="top">OH this is just GORGEOUS!!  Whatever it is.  This is so artistic and delicate.</td>', 'OH this is just GORGEOUS!!  Whatever it is.  This is so artistic and delicate.', '2010-07-12 03:24:48.000000', NULL, 1),
