(6089086, 897104, 27686, '<td valign="top">Great texture, well lit.</td>', 'Great texture, well lit.', '2010-07-12 03:28:00.000000', NULL, 1),
(6089088, 897116, 96751, '<td valign="top">Very moody image.  Love the way the trees appear in the fog, in contrast to the sharpness of the well in the foreground.  Nicely balanced too.</td>', 'Very moody image.  Love the way the trees appear in the fog, in contrast to the sharpness of the well in the foreground.  Nicely balanced too.', '2010-07-12 03:28:39.000000', NULL, 1),
