(6089092, 897081, 96751, '<td valign="top">Beautiful.  The deep green background really compliments the golden tone.s</td>', 'Beautiful.  The deep green background really compliments the golden tone.s', '2010-07-12 03:32:12.000000', NULL, 1),
(6089106, 897152, 101399, '<td valign="top">Not a bad shot, but I don''t think it really fits this challenge...</td>', 'Not a bad shot, but I don''t think it really fits this challenge...', '2010-07-12 04:00:51.000000', NULL, 1),
