(6089205, 897174, 97073, '<td valign="top">Looks like you used direct flash here? Gives a very harsh unflattering light. The image could have been good if a softer/indirect light source was used.</td>', 'Looks like you used direct flash here? Gives a very harsh unflattering light. The image could have been good if a softer/indirect light source was used.', '2010-07-12 07:45:18.000000', NULL, 1),
(6089237, 896388, 45706, '<td valign="top">REALLY like this one!</td>', 'REALLY like this one!', '2010-07-12 08:57:11.000000', NULL, 1),
