(6090343, 896927, 83313, '<td valign="top">Rusty crusty heaven.</td>', 'Rusty crusty heaven.', '2010-07-12 23:53:43.000000', NULL, 1),
(6090345, 897100, 83313, '<td valign="top">Yuk. I guess this dead frog is both weathered and withered.</td>', 'Yuk. I guess this dead frog is both weathered and withered.', '2010-07-12 23:54:58.000000', NULL, 1),
(6090348, 897012, 83313, '<td valign="top">Where''s the one tire? I don''t see any tires...</td>', 'Where''s the one tire? I don''t see any tires...', '2010-07-12 23:55:38.000000', NULL, 1),
(6090350, 897172, 83313, '<td valign="top">Of course it''s still standing. Plastic and fiberglass porta-potties will be the one thing remaining of our culture for future archeologists.</td>', 'Of course it''s still standing. Plastic and fiberglass porta-potties will be the one thing remaining of our culture for future archeologists.', '2010-07-12 23:56:56.000000', NULL, 1),
(6090353, 896494, 83313, '<td valign="top">The tonemapping looks good on the old house, though I find the trees a little heavy on the saturation. It''s actually the yellow channel that gives foliage that strong appearance. I usually reduce the yellows a bit, but that''s really a personal preference thing.</td>', 'The tonemapping looks good on the old house, though I find the trees a little heavy on the saturation. It''s actually the yellow channel that gives foliage that strong appearance. I usually reduce the yellows a bit, but that''s really a personal preference thing.', '2010-07-12 23:59:00.000000', NULL, 1),
(6090356, 896499, 83313, '<td valign="top">I like the partial desat treatment, but it looks like the focus is more on the background foliage than the tractor.</td>', 'I like the partial desat treatment, but it looks like the focus is more on the background foliage than the tractor.', '2010-07-13 00:00:15.000000', NULL, 1),
(6090357, 897097, 83313, '<td valign="top">I''ll be expecting this one to come in near the top.</td>', 'I''ll be expecting this one to come in near the top.', '2010-07-13 00:00:38.000000', NULL, 1),
(6090361, 896943, 83313, '<td valign="top">What an awesome portrait! This could be a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=49643" rel="nofollow" target="_blank">bnilesh</a> entry. If not, then that is to be taken as a compliment.</td>', 'What an awesome portrait! This could be a  bnilesh entry. If not, then that is to be taken as a compliment.', '2010-07-13 00:04:11.000000', NULL, 1),
(6090390, 896365, 83313, '<td valign="top">I just watched Alien vs Predator the other day, so this reminds me of the alien eggs.</td>', 'I just watched Alien vs Predator the other day, so this reminds me of the alien eggs.', '2010-07-13 00:42:49.000000', NULL, 1),
(6090400, 897103, 39057, '<td valign="top">When I saw this in the thumbnails with the title I started laughing out loud ! High score for that.</td>', 'When I saw this in the thumbnails with the title I started laughing out loud ! High score for that.', '2010-07-13 01:25:22.000000', NULL, 1),
(6090424, 896960, 5822, '<td valign="top">So simple yet so effective in conveying an ominous foreboding event. I get the chills looking at it. Seems straight out of a horror flick. The bird adds the perfect touch.</td>', 'So simple yet so effective in conveying an ominous foreboding event. I get the chills looking at it. Seems straight out of a horror flick. The bird adds the perfect touch.', '2010-07-13 02:37:52.000000', NULL, 1),
(6090425, 896455, 5822, '<td valign="top">Over processed to my eyes.</td>', 'Over processed to my eyes.', '2010-07-13 02:43:40.000000', NULL, 1),
(6090429, 896651, 27686, '<td valign="top">Nice pic, focus looks out.</td>', 'Nice pic, focus looks out.', '2010-07-13 02:57:12.000000', NULL, 1),
(6090434, 896940, 27686, '<td valign="top">This is a great shot, bit of a halo around the trees behind the truck, needed finer editing there. Great color &amp; contrast.</td>', 'This is a great shot, bit of a halo around the trees behind the truck, needed finer editing there. Great color & contrast.', '2010-07-13 03:02:09.000000', NULL, 1),
(6090437, 897028, 20168, '<td valign="top">good angle for composition but more of side of vehicle would have added a bit, still a beauty of an entry</td>', 'good angle for composition but more of side of vehicle would have added a bit, still a beauty of an entry', '2010-07-13 03:05:14.000000', NULL, 1),
(6090438, 896715, 20168, '<td valign="top">great macro!</td>', 'great macro!', '2010-07-13 03:05:28.000000', NULL, 1),
(6090440, 896987, 20168, '<td valign="top">though I''m not a fan of HDR (due to its overuse on DPC) this entry seems to allow the added wonderland HDR provides. Nice work</td>', 'though I''m not a fan of HDR (due to its overuse on DPC) this entry seems to allow the added wonderland HDR provides. Nice work', '2010-07-13 03:06:28.000000', NULL, 1),
(6090441, 896590, 20168, '<td valign="top">great colors (even if they may have been bumped a bit in PP) and a sweet macro</td>', 'great colors (even if they may have been bumped a bit in PP) and a sweet macro', '2010-07-13 03:06:58.000000', NULL, 1),
(6090442, 896915, 20168, '<td valign="top">Oh my what a wonder! cool entry</td>', 'Oh my what a wonder! cool entry', '2010-07-13 03:07:16.000000', NULL, 1),
(6090443, 896138, 20168, '<td valign="top">I love negative space and the simplicity of this entry</td>', 'I love negative space and the simplicity of this entry', '2010-07-13 03:07:37.000000', NULL, 1),
