INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6090446, 896962, 20168, '<td valign="top">great angle and use of post processing to capture this wonder</td>', 'great angle and use of post processing to capture this wonder', '2010-07-13 03:09:14.000000', NULL, 1),
(6090447, 896943, 5822, '<td valign="top">Beautiful portrait with excellent textures and tones, perfect DOF (all facial features and headdress in focus), good BG/subject separation, so technically excellent. With all of the hackneyed Topaz processing I''ve seen so far in this challenge, here it''s done very well and to good effect. The most salient aspects to this portrait for me are his eyes and the way the creases in his turbine mirror the wrinkles of his skin. Excellent job!</td>', 'Beautiful portrait with excellent textures and tones, perfect DOF (all facial features and headdress in focus), good BG/subject separation, so technically excellent. With all of the hackneyed Topaz processing I''ve seen so far in this challenge, here it''s done very well and to good effect. The most salient aspects to this portrait for me are his eyes and the way the creases in his turbine mirror the wrinkles of his skin. Excellent job!', '2010-07-13 03:09:17.000000', NULL, 1),
(6090448, 896788, 20168, '<td valign="top">good bokeh background to add poetry to the foreground</td>', 'good bokeh background to add poetry to the foreground', '2010-07-13 03:09:47.000000', NULL, 1),
(6090450, 896922, 20168, '<td valign="top">though I have no idea what these are, nor how they are going to be accepted by the DPC voters [likely not :(] I happen to love this entry and see that soft erosion/weathering upon this design. You''ve got my 9</td>', 'though I have no idea what these are, nor how they are going to be accepted by the DPC voters [likely not :(] I happen to love this entry and see that soft erosion/weathering upon this design. You''ve got my 9', '2010-07-13 03:11:12.000000', NULL, 1),
(6090451, 896946, 20168, '<td valign="top">nice lighting</td>', 'nice lighting', '2010-07-13 03:11:37.000000', NULL, 1),
(6090453, 896920, 20168, '<td valign="top">love the colors and "feel" of the image</td>', 'love the colors and "feel" of the image', '2010-07-13 03:12:00.000000', NULL, 1),
(6090454, 896683, 20168, '<td valign="top">too flat for my taste of composition but great subject</td>', 'too flat for my taste of composition but great subject', '2010-07-13 03:12:27.000000', NULL, 1),
(6090456, 896301, 20168, '<td valign="top">I like the non-violent message in this and the colors</td>', 'I like the non-violent message in this and the colors', '2010-07-13 03:12:52.000000', NULL, 1),
(6090457, 896734, 20168, '<td valign="top">a higher and slightly altered angle would have improved this IMHO but beautiful subject</td>', 'a higher and slightly altered angle would have improved this IMHO but beautiful subject', '2010-07-13 03:13:25.000000', NULL, 1),
(6090459, 897174, 20168, '<td valign="top">cellar bench for cellar dwellers!</td>', 'cellar bench for cellar dwellers!', '2010-07-13 03:13:50.000000', NULL, 1),
(6090461, 897064, 20168, '<td valign="top">HDR is used too much IMHO on DPC but this image with HDR moves into the realm of memory and a beautiful historic past at that!</td>', 'HDR is used too much IMHO on DPC but this image with HDR moves into the realm of memory and a beautiful historic past at that!', '2010-07-13 03:14:47.000000', NULL, 1),
(6090463, 897155, 20168, '<td valign="top">nice contrast between nature and human built</td>', 'nice contrast between nature and human built', '2010-07-13 03:15:16.000000', NULL, 1),
(6090464, 896763, 20168, '<td valign="top">IMHO this is overly processed and takes away from the image, but then my image is also overly processed so it likely is what you were aiming at. Hmmm, the texture of the shore is certainly dramatic and pronounced boldly!</td>', 'IMHO this is overly processed and takes away from the image, but then my image is also overly processed so it likely is what you were aiming at. Hmmm, the texture of the shore is certainly dramatic and pronounced boldly!', '2010-07-13 03:16:50.000000', NULL, 1),
(6090465, 897149, 20168, '<td valign="top">I like the angle</td>', 'I like the angle', '2010-07-13 03:17:09.000000', NULL, 1),
(6090467, 897026, 20168, '<td valign="top">this may be just a twinge oversharpened for my eye but a lovely capture</td>', 'this may be just a twinge oversharpened for my eye but a lovely capture', '2010-07-13 03:17:41.000000', NULL, 1),
(6090469, 897048, 20168, '<td valign="top">fun! the tonal range is a bit flat IMHO</td>', 'fun! the tonal range is a bit flat IMHO', '2010-07-13 03:18:05.000000', NULL, 1),
(6090470, 896966, 27686, '<td valign="top">This pic would have looked better if you made it darker and put more contrast in to enhance the corrosion, great shot.</td>', 'This pic would have looked better if you made it darker and put more contrast in to enhance the corrosion, great shot.', '2010-07-13 03:18:24.000000', NULL, 1),
(6090471, 897175, 20168, '<td valign="top">playful!</td>', 'playful!', '2010-07-13 03:18:28.000000', NULL, 1),
