(6090474, 896903, 20168, '<td valign="top">composition is too "flat", colors are great</td>', 'composition is too "flat", colors are great', '2010-07-13 03:19:49.000000', NULL, 1),
(6090475, 896960, 27686, '<td valign="top">What a great photo!</td>', 'What a great photo!', '2010-07-13 03:19:52.000000', NULL, 1),
(6090477, 897109, 20168, '<td valign="top">good choice for B/W</td>', 'good choice for B/W', '2010-07-13 03:20:03.000000', NULL, 1),
(6090478, 896894, 20168, '<td valign="top">good eye for detail</td>', 'good eye for detail', '2010-07-13 03:20:20.000000', NULL, 1),
