(6096458, 896960, 75618, '<td valign="top">Clouds are a bit overdone but this is wonderful! 9</td>', 'Clouds are a bit overdone but this is wonderful! 9', '2010-07-18 22:41:02.000000', NULL, 1),
(6096462, 897164, 86799, '<td valign="top">Beautiful.  Not sure about the vignette, it seems to unbalance the comp, IMO.</td>', 'Beautiful.  Not sure about the vignette, it seems to unbalance the comp, IMO.', '2010-07-18 22:42:15.000000', NULL, 1),
(6096465, 896681, 86799, '<td valign="top">2nd look...stirs the imagination...I hear the last few drips from the trees, feel a gentle cool breeze through the open window, and smell the drying shoes.  Think I''ll bump the score a bit.</td>', '2nd look...stirs the imagination...I hear the last few drips from the trees, feel a gentle cool breeze through the open window, and smell the drying shoes.  Think I''ll bump the score a bit.', '2010-07-18 22:43:00.000000', NULL, 1),
(6096467, 896681, 75618, '<td valign="top">I wonder if this would work better with the shoes in focus and the window being blurry. I still like this image regardless. 8</td>', 'I wonder if this would work better with the shoes in focus and the window being blurry. I still like this image regardless. 8', '2010-07-18 22:43:17.000000', NULL, 1),
(6096468, 897104, 86799, '<td valign="top">The texture of the magnolia makes this.  Well done.</td>', 'The texture of the magnolia makes this.  Well done.', '2010-07-18 22:44:08.000000', NULL, 1),
(6096470, 896481, 94235, '<td valign="top">Well processed. The contrast in the clouds adds volumes to this shot.</td>', 'Well processed. The contrast in the clouds adds volumes to this shot.', '2010-07-18 22:44:26.000000', NULL, 1),
(6096472, 896881, 94235, '<td valign="top">Lovely subtle tones. The lighting of the tree makes it more of a standout feature. Well shot.</td>', 'Lovely subtle tones. The lighting of the tree makes it more of a standout feature. Well shot.', '2010-07-18 22:45:58.000000', NULL, 1),
(6096474, 897165, 86799, '<td valign="top">The composition looks a little cluttered to me.  It a good pic, but there''s just a few too many elements...maybe better w/o the mower?</td>', 'The composition looks a little cluttered to me.  It a good pic, but there''s just a few too many elements...maybe better w/o the mower?', '2010-07-18 22:46:15.000000', NULL, 1),
(6096475, 897115, 86799, '<td valign="top">Love this picture.  The bright sunshine makes it all look rather comfortable for the dog, but that''s OK.  He IS weathered, and it''s a great pic of a great dog.  Bet he wasn''t forgotten long.</td>', 'Love this picture.  The bright sunshine makes it all look rather comfortable for the dog, but that''s OK.  He IS weathered, and it''s a great pic of a great dog.  Bet he wasn''t forgotten long.', '2010-07-18 22:47:09.000000', NULL, 1),
(6096478, 897151, 75618, '<td valign="top">Great textures and tones. I think this would have been wonderful with a bit of perspective correction.</td>', 'Great textures and tones. I think this would have been wonderful with a bit of perspective correction.', '2010-07-18 22:47:55.000000', NULL, 1),
(6096484, 897116, 75618, '<td valign="top">I''m torn about this. The landscape in the BG is wonderful but I feel like it makes your "main subject" just an inconsequential part of the picture. 7</td>', 'I''m torn about this. The landscape in the BG is wonderful but I feel like it makes your "main subject" just an inconsequential part of the picture. 7', '2010-07-18 22:53:34.000000', NULL, 1),
(6096486, 896940, 94235, '<td valign="top">Like the end result of processing used here. May have cropped the left side, to the edge of the tree, to put the truck in the "thirds" position and centre the cloud effect in the background. Nice take all the same.</td>', 'Like the end result of processing used here. May have cropped the left side, to the edge of the tree, to put the truck in the "thirds" position and centre the cloud effect in the background. Nice take all the same.', '2010-07-18 22:53:50.000000', NULL, 1),
(6096490, 896987, 94235, '<td valign="top">Well processed. Gives the viewer the feel of standing there right beside it!</td>', 'Well processed. Gives the viewer the feel of standing there right beside it!', '2010-07-18 22:55:01.000000', NULL, 1),
