(6108231, 897163, 11854, '<td valign="top">This is awesome! It looks like Fantasy Island on a flyover!</td>', 'This is awesome! It looks like Fantasy Island on a flyover!', '2010-07-29 00:48:33.000000', NULL, 0),
(6108686, 896809, 40718, '<td valign="top">This shot caught my eye because I think you did well with your composition and using the wide angle to distort the cabin.  The trees in the background both help and hurt.  It is nice to have something else for the eye to see, but trees like that often wind up all jumbled and muddy, especially at these small canvas sizes.  You did well to control the sky and your processing overall is very good.</td>', 'This shot caught my eye because I think you did well with your composition and using the wide angle to distort the cabin.  The trees in the background both help and hurt.  It is nice to have something else for the eye to see, but trees like that often wind up all jumbled and muddy, especially at these small canvas sizes.  You did well to control the sky and your processing overall is very good.', '2010-07-29 15:51:51.000000', NULL, 0),
(6110113, 896950, 40718, '<td valign="top">I love the colors in this one and the subject, but again I feel just a tiny bit cramped.  Try to loosen up your crop if you can.  Sometimes the crop is the way it is for a reason (something ugly being cut out), but you may like the results if you let your landscapes and animals breathe in the image just a bit.</td>', 'I love the colors in this one and the subject, but again I feel just a tiny bit cramped.  Try to loosen up your crop if you can.  Sometimes the crop is the way it is for a reason (something ugly being cut out), but you may like the results if you let your landscapes and animals breathe in the image just a bit.', '2010-07-31 01:16:12.000000', NULL, 0),
(6112476, 896960, 44877, '<td valign="top">This is so good.</td>', 'This is so good.', '2010-08-01 22:07:58.000000', NULL, 0),
